model:
namespace core
decodes Currencies { - 1 CNY: 'CNY' - 2 USD: 'USD' }
type money = decimal[6, 2]
entity Item {
    id id: integer
    static attr text: string
    static attr flag: bool
    static attr count: integer
    static attr day: date
    static attr amount: money
    static attr currency: code<Currencies>
    static attr other: Item
}
entity Child inherits Item { @override static attr flag: exact<true> }

extend Item { @temporal(day: date) snapshot attr price: money }

